INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'اگه کسی که دوستش دارید بهتون بگه "فقط دوستیم"، چیکار میکنید؟', 'pending', '2026-09-19T10:34:01.970Z' FROM _tgmap m WHERE m.tg = -10019;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'تو دانشگاه یه نفر هست که هر روز میبینمش ولی هرگز جرئت نکردم باهاش حرف بزنم', 'pending', '2026-09-19T10:34:01.971Z' FROM _tgmap m WHERE m.tg = -10002;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'آیا اولین پیام زدن از طرف دختر عادیه یا هنوز سخته؟', 'pending', '2026-09-19T10:34:01.972Z' FROM _tgmap m WHERE m.tg = -10008;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'با یکی از اینجا آشنا شدم، ۳ ماه چت کردیم، قرار شد ببینیم همدیگه رو... ولی من لغو کردم چون میترسیدم واقعیت با انتظاراتم فرق داشته باشه', 'pending', '2026-09-19T10:34:01.974Z' FROM _tgmap m WHERE m.tg = -10019;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'چجوری بفهمم کسی واقعاً بهم علاقه‌منده یا فقط وقتمو میگیره؟', 'pending', '2026-09-19T10:34:01.977Z' FROM _tgmap m WHERE m.tg = -10008;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'เคย یه بار اعتراف کردم که عاشقشم ولی اون گفت "ممنون"... از اون روز دیگه هیچوقت اعتراف نکردم', 'pending', '2026-09-19T10:34:01.979Z' FROM _tgmap m WHERE m.tg = -10003;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'امروز یه پیام اشتباهی فرستادم برای کسی که دوستش دارم... الان دارم فکر میکنم چجوری نجات بدم', 'pending', '2026-09-19T10:34:01.982Z' FROM _tgmap m WHERE m.tg = -10020;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'نظرتون درباره دوستیابی آنلاین چیه؟ واقعاً آدمای خوب پیدا میشن؟', 'pending', '2026-09-19T10:34:01.985Z' FROM _tgmap m WHERE m.tg = -10016;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'تو محل کارم یه نفر هست که هر روز صبح وقتی میاد، قلبم تندتر میزنه ولی نمیدونم چجوری بگم', 'pending', '2026-09-19T10:34:01.987Z' FROM _tgmap m WHERE m.tg = -10007;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'اگه طرف مقابلتون زیاد آنلاین نباشه و دیر جواب بده، نشونه چیه؟', 'pending', '2026-09-19T10:34:01.989Z' FROM _tgmap m WHERE m.tg = -10018;
INSERT INTO confessions (bot_id, user_id, text, status, created_at) SELECT 'a6b194d9-a735-499a-b1f3-bd951cc99468', m.uid, 'دیشب خواب دیدم با کسی که دوستش دارم رفتیم سفر... صبح که بیدار شدم فهمیدم فقط یه خواب بود', 'pending', '2026-09-19T10:34:01.991Z' FROM _tgmap m WHERE m.tg = -10004;
